func (r *mutationResolver) AddApprovalComment(ctx context.Context, requestID string, body string) (*ApprovalRequest, error) {
	resp, err := r.Workflow.AddApprovalComment(ctx, &workflowv1.AddApprovalCommentRequest{
		Actor: workflowActorOf(ctx), RequestId: requestID, Body: body,
	})
	if err != nil {
		return nil, err
	}
	out := gqlApproval(resp.GetRequest())
	r.enrichApprovalNames(ctx, []*ApprovalRequest{out})
	return out, nil
}

// RotateSecret is the resolver for the rotateSecret field. Manual rotation
// calls the vault directly (not the workflow) so the full RACI actor context
// is used for firewall enforcement.
func (r *mutationResolver) RotateSecret(ctx context.Context, secretID string) (bool, error) {
	// A manual rotation must not run while the secret is checked out — it would
	// invalidate the credential the active holder is using. (System rotate-on-
	// check-in and break-glass forced rotation are separate paths.)
	if err := r.refuseWhileCheckedOut(ctx, secretID, "rotate"); err != nil {
		return false, err
	}
	if _, err := r.Vault.EnqueueRotation(ctx, &vaultv1.EnqueueRotationRequest{
		Actor: actorOf(ctx), SecretId: secretID, Reason: "manual",
	}); err != nil {
		return false, err
	}
	return true, nil
}

