// OpenSSHSession is the resolver for the openSshSession field.
func (r *mutationResolver) OpenSSHSession(ctx context.Context, secretID string) (*SSHSessionTicket, error) {
	actor := actorOf(ctx)
	sec, err := r.Vault.GetSecret(ctx, &vaultv1.GetSecretRequest{Actor: actor, Id: secretID})
	if err != nil {
		return nil, err
	}
	if sec.GetSecret().GetTypeId() != "type-ssh-key" {
		return nil, fmt.Errorf("secret is not an SSH key")
	}
	targetID := sec.GetSecret().GetTargetId()
	if targetID == "" {
		return nil, fmt.Errorf("secret has no target host")
	}
	host, port, hostKeys, err := r.resolveSSHEndpoint(ctx, targetID)
	if err != nil {
		return nil, err
	}
	// Non-sensitive username (no audited reveal).
	fields, err := r.Vault.GetSecretFields(ctx, &vaultv1.GetSecretFieldsRequest{Actor: actor, Id: secretID})
	if err != nil {
		return nil, err
	}
	// Hand the broker a REFERENCE (secret id + actor), not the key. The broker
	// can run >1 replica: it stores only the reference in a shared ticket store
	// and, on the pod that terminates the SSH session, reveals the private key
	// from the vault itself (RevealSecretField, RBAC-gated + audited) with this
	// same actor. So the key is never fetched/forwarded here — it stays in the
	// vault until the redeeming pod needs it, and RBAC/audit are unchanged
	// because the broker passes this actor straight through.
	resp, err := r.SSHBroker.CreateSession(ctx, &sshbrokerv1.CreateSessionRequest{
		Host:        host,
		Port:        safeconv.Int32(port),
		Username:    fields.GetFields()["username"],
		ActorUserId: actor.GetUserId(),
		SecretId:    secretID,
		TargetId:    targetID,
		TtlSeconds:  30,
		HostKeys:    hostKeys,
		Actor:       brokerActor(actor),
	})
	if err != nil {
		return nil, err
	}
	return &SSHSessionTicket{
		WsURL:            resp.GetWsUrl(),
		Ticket:           resp.GetTicket(),
		SessionID:        resp.GetSessionId(),
		ExpiresInSeconds: int(resp.GetExpiresInSeconds()),
	}, nil
}

