// SecretStats is the resolver for the secretStats subscription: it pushes the
// acting user's dashboard rollup over the WebSocket. RACI scoping is automatic —
// actorOf(ctx) carries the socket's authenticated actor (resolved from the
// session cookie in the WS InitFunc), so GetSecretStats returns exactly the
// same readable-secrets rollup as the secretStats query. It emits once
// immediately on subscribe, then on a ticker pushes only when the value changed,
// and stops when the client disconnects (ctx.Done()).
func (r *subscriptionResolver) SecretStats(ctx context.Context) (<-chan *SecretStats, error) {
	fetch := func() (*SecretStats, error) {
		resp, err := r.Vault.GetSecretStats(ctx, &vaultv1.GetSecretStatsRequest{Actor: actorOf(ctx)})
		if err != nil {
			return nil, err
		}
		st := resp.GetStats()
		return &SecretStats{
			Total: int(st.GetTotal()), ExpiringSoon: int(st.GetExpiringSoon()),
			Expired: int(st.GetExpired()), Drift: int(st.GetDrift()),
		}, nil
	}
	// Resolve the first snapshot synchronously so an auth/RACI/backend error
	// surfaces as a failed subscription rather than a silently empty stream.
	first, err := fetch()
	if err != nil {
		return nil, err
	}
	ch := make(chan *SecretStats, 1)
	ch <- first
	go func() {
		defer close(ch)
		last := *first
		ticker := time.NewTicker(secretStatsPollInterval)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				next, ferr := fetch()
				if ferr != nil {
					// Transient backend/identity blip: skip this tick, keep the
					// socket open, try again next interval.
					continue
				}
				if *next == last {
					continue
				}
				last = *next
				select {
				case ch <- next:
				case <-ctx.Done():
					return
				}
			}
		}
	}()
	return ch, nil
}

// Mutation returns MutationResolver implementation.
func (r *Resolver) Mutation() MutationResolver { return &mutationResolver{r} }

// Query returns QueryResolver implementation.
func (r *Resolver) Query() QueryResolver { return &queryResolver{r} }

// Subscription returns SubscriptionResolver implementation.
func (r *Resolver) Subscription() SubscriptionResolver { return &subscriptionResolver{r} }

type mutationResolver struct{ *Resolver }
type queryResolver struct{ *Resolver }
type subscriptionResolver struct{ *Resolver }
